WITH RECURSIVE Months AS (SELECT 1 AS month UNION ALL SELECT month + 1 FROM Months WHERE month < 12), MonthlyTotals AS (SELECT m.month, IFNULL(SUM(ar.ride_distance), 0) AS tot_dist, IFNULL(SUM(ar.ride_duration), 0) AS tot_dur FROM Months m LEFT JOIN Rides r ON YEAR(r.requested_at) = 2020 AND MONTH(r.requested_at) = m.month LEFT JOIN AcceptedRides ar ON r.ride_id = ar.ride_id GROUP BY m.month) SELECT month, ROUND((tot_dist + LEAD(tot_dist, 1) OVER (ORDER BY month) + LEAD(tot_dist, 2) OVER (ORDER BY month)) / 3.0, 2) AS average_ride_distance, ROUND((tot_dur + LEAD(tot_dur, 1) OVER (ORDER BY month) + LEAD(tot_dur, 2) OVER (ORDER BY month)) / 3.0, 2) AS average_ride_duration FROM MonthlyTotals WHERE month <= 10 ORDER BY month;
